use crate::*;
use serde_json::{Value, json};
use std::collections::{BTreeMap, BTreeSet};

fn spec(case: &str) -> Value {
    let p: Value = serde_json::from_str(PROTOCOL).unwrap();
    let mut s = p["definitions"][case].clone();
    s.as_object_mut().unwrap().remove("longer_lengths");
    s
}

#[test]
fn source_denominators_and_independent_word_answers() -> Result<()> {
    // Frozen historical GPT denominators; not generated by this implementation.
    let counts = [
        [(872, 624), (2176, 1435), (4224, 2961)],
        [(808, 560), (2112, 1371), (4160, 2897)],
        [(892, 456), (2176, 796), (4224, 1264)],
        [(128, 128), (128, 128), (128, 128)],
        [(542, 478), (584, 520), (566, 502)],
        [(542, 524), (584, 570), (566, 549)],
        [(884, 463), (2176, 521), (4224, 514)],
    ];
    for (index, case) in CASES.iter().enumerate() {
        let d = dataset::build(case)?;
        assert_eq!(
            d.task.vocab,
            if [3, 6].contains(&index) { 100 } else { 229 }
        );
        assert_eq!(d.task.splits.len(), 11);
        assert_eq!(d.task.selection, "validation/novel");
        let train: BTreeSet<_> = d.task.splits["train"].iter().map(|e| &e.prompt).collect();
        for (name, rows) in &d.task.splits {
            for e in rows {
                let word = &e.prompt[usize::from(index != 1)..e.prompt.len() - 1];
                assert!(word.iter().all(|&t| (36..100).contains(&t)));
                let mut frequencies = BTreeMap::<i64, usize>::new();
                for t in word {
                    *frequencies.entry(*t).or_default() += 1;
                }
                let first = |t: i64| word.iter().position(|&x| x == t).unwrap();
                let mut order: Vec<_> = frequencies.keys().copied().collect();
                order.sort_by_key(|&t| first(t));
                let mut expected = if [0, 2, 6].contains(&index) {
                    vec![1]
                } else {
                    vec![]
                };
                match index {
                    0 | 1 => expected.extend(word.iter().map(|t| 100 + frequencies[t] as i64)),
                    2 => expected.extend(word.iter().map(|t| {
                        100 + frequencies
                            .values()
                            .filter(|&&c| c == frequencies[t])
                            .count() as i64
                    })),
                    3..=5 => {
                        let maximum = *frequencies.values().max().unwrap();
                        let winners: Vec<_> = frequencies
                            .iter()
                            .filter(|(_, c)| **c == maximum)
                            .map(|(t, _)| *t)
                            .collect();
                        assert_eq!(winners.len(), 1);
                        if index == 4 {
                            order.sort_by_key(|t| (frequencies[t], first(*t)));
                        }
                        if index != 3 {
                            for t in order {
                                expected.extend([100 + frequencies[&t] as i64, t]);
                            }
                        }
                        expected.push(winners[0]);
                    }
                    6 => {
                        order.sort_by_key(|t| (std::cmp::Reverse(frequencies[t]), first(*t)));
                        expected.extend(order);
                        expected.resize(word.len() + 1, 1);
                    }
                    _ => unreachable!(),
                }
                expected.push(17);
                assert_eq!(e.answer, expected);
                assert_eq!(e.prompt.last(), Some(&18));
                if index != 1 {
                    assert_eq!(e.prompt.first(), Some(&1));
                }
                assert!(e.answer.len() <= e.limit);
                assert_eq!(
                    e.tokens,
                    e.prompt
                        .iter()
                        .chain(e.answer[..e.answer.len() - 1].iter())
                        .copied()
                        .collect::<Vec<_>>()
                );
                assert_eq!(
                    e.targets,
                    std::iter::repeat_n(-100, e.prompt.len() - 1)
                        .chain(e.answer.iter().copied())
                        .collect::<Vec<_>>()
                );
                assert!(e.changes[..e.prompt.len() - 1].iter().all(|c| !*c));
                for (i, &target) in e.answer.iter().enumerate() {
                    assert_eq!(
                        e.changes[e.prompt.len() - 1 + i],
                        i == 0 || e.answer[i - 1] != target
                    );
                }
                if name.ends_with("/novel") {
                    assert!(!train.contains(&e.prompt));
                }
            }
        }
        for (split, (targets, transitions)) in ["test", "test/length-32", "test/length-64"]
            .into_iter()
            .zip(counts[index])
        {
            let rows = &d.task.splits[split];
            assert_eq!(rows.len(), 64);
            assert_eq!(
                rows.iter().map(|e| e.answer.len()).sum::<usize>(),
                targets,
                "{case}/{split}"
            );
            assert_eq!(
                rows.iter().flat_map(|e| &e.changes).filter(|&&c| c).count(),
                transitions,
                "{case}/{split}"
            );
        }
        assert_eq!(
            wire::tensor_hash(&d.task.splits["train"]),
            wire::tensor_hash(&d.task.splits["train_clean"])
        );
    }
    Ok(())
}

#[test]
fn formats_share_problems_and_keep_odd_stream_prefixes() -> Result<()> {
    for split in ["train", "validation", "test"] {
        let rows: Vec<_> = CASES
            .iter()
            .map(|c| dataset::generate(&spec(c), split, 17).unwrap())
            .collect();
        for (a, b) in rows[0].iter().zip(&rows[1]) {
            assert_eq!(&a.prompt[1..], b.prompt);
        }
        for (a, b) in [(&rows[3], &rows[4]), (&rows[4], &rows[5])] {
            for (p, q) in a.iter().zip(b) {
                assert_eq!(p.prompt, q.prompt);
            }
        }
        for (i, case) in CASES.iter().enumerate() {
            let longer = dataset::generate(&spec(case), split, 22)?;
            assert_eq!(
                wire::tensor_hash(&rows[i]),
                wire::tensor_hash(&longer[..17])
            );
        }
    }
    assert!(dataset::identity(&spec(CASES[3]))["number_limit"].is_null());
    assert_eq!(dataset::identity(&spec(CASES[3]))["symbols"], 64);
    Ok(())
}

#[test]
fn stable_frequency_order_and_single_occurrence_tie_repair() {
    let word = [40, 38, 40, 45, 38, 37, 40];
    let expected = [
        vec![1, 103, 102, 103, 101, 102, 101, 103, 17],
        vec![103, 102, 103, 101, 102, 101, 103, 17],
        vec![1, 101, 101, 101, 102, 101, 102, 101, 17],
        vec![40, 17],
        vec![101, 45, 101, 37, 102, 38, 103, 40, 40, 17],
        vec![103, 40, 102, 38, 101, 45, 101, 37, 40, 17],
        vec![1, 40, 38, 45, 37, 1, 1, 1, 17],
    ];
    for (i, case) in CASES.iter().enumerate() {
        let s = spec(case);
        let c = generator::Config {
            task: s["task"].as_str().unwrap(),
            symbols: 64,
            bos: i != 1,
            scratchpad: s["scratchpad"].as_str().unwrap_or("none"),
            numbers: dataset::uses_numbers(&s),
        };
        assert_eq!(generator::from_word(&c, &word).answer, expected[i]);
    }
    for seed in 0..32 {
        let before = [44, 37, 42, 44, 37, 42];
        let mut after = before;
        generator::repair_tie(&mut after, &mut Random::new(seed));
        assert_eq!(
            before.iter().zip(after).filter(|(a, b)| **a != *b).count(),
            1
        );
        let counts = generator::counts(&after);
        assert_eq!(counts.iter().filter(|p| p.1 == 3).count(), 1);
        assert!(after.iter().all(|t| before.contains(t)));
    }
}

#[test]
fn final_answer_does_not_replace_exact_and_rollout_uses_own_tokens() -> Result<()> {
    let answer = [102, 40, 40, 17];
    assert!(scoring::final_answer(&answer, &[99, 40, 17], true)?);
    assert!(!scoring::score(&answer, &[99, 40, 17])?.exact);
    assert!(!scoring::final_answer(&answer, &[99, 40, 17], false)?);
    assert!(!scoring::final_answer(&answer, &[40, 40], true)?);
    assert!(!scoring::final_answer(&answer, &[17], true)?);
    let mut seen = vec![];
    let output = scoring::rollout(&[1, 40, 18], 6, 229, |p| {
        seen.push(p.to_vec());
        Ok(if p.last() == Some(&18) { 99 } else { 17 })
    })?;
    assert_eq!(output, vec![99, 17]);
    assert_eq!(seen[1].last(), Some(&99));
    let endless = scoring::rollout(&[1, 40, 18], 6, 229, |_| Ok(40))?;
    assert_eq!(endless.len(), 6);
    assert!(!scoring::score(&answer, &endless)?.ended);
    Ok(())
}

#[test]
fn unseen_numeric_outputs_are_reported_without_identification() -> Result<()> {
    let d = dataset::build(CASES[0])?;
    let m = dataset::metadata(&d);
    assert_eq!(
        m["output_label_coverage"]["train"]["unseen_target_occurrences"],
        0
    );
    assert!(
        m["output_label_coverage"]["test/length-64"]["unseen_target_occurrences"]
            .as_u64()
            .unwrap()
            > 0
    );
    assert_eq!(
        m["output_label_coverage"]["test/length-64"]["identifies_missing_labels"],
        false
    );
    Ok(())
}

#[test]
fn invalid_inputs_and_changed_pins_refuse() -> Result<()> {
    let mut s = spec(CASES[4]);
    assert!(dataset::generate(&s, "bad", 8).is_err());
    assert!(dataset::generate(&s, "train", 0).is_err());
    assert!(dataset::generate(&s, "train", 20001).is_err());
    s["length"] = json!(129);
    assert!(dataset::generate(&s, "train", 8).is_err());
    s["length"] = json!(16);
    s["min_length"] = json!(2);
    assert!(dataset::generate(&s, "train", 8).is_err());
    s["min_length"] = json!(8);
    s["scratchpad"] = json!("invalid");
    assert!(dataset::generate(&s, "train", 8).is_err());
    assert!(dataset::build("suite-parity-none").is_err());
    let root = std::env::temp_dir().join(format!("frequency-data-pins-{}", std::process::id()));
    std::fs::create_dir(&root)?;
    let path = root.join("input.json");
    std::fs::write(&path, b"{}\n")?;
    assert!(inventory::read_pinned(&path, &hash(b"{}\n")).is_ok());
    assert!(inventory::read_pinned(&path, &hash(b"[]\n")).is_err());
    assert!(inventory::prepare(&path, &path, &path).is_err());
    std::fs::remove_dir_all(root)?;
    Ok(())
}
